import { useEffect, useState } from 'react';
import { useLocation } from 'react-router';
import { useDocs } from 'data/data';

import Button from 'components/Button';

function Document() {
    const { getDoc, isLoading } = useDocs()
    const location = useLocation()

    const [doc, setDoc] = useState(null);
    const [pdfLoading, setPdfLoading] = useState(true);
    const [pdfError, setPdfError] = useState(false);

    let hashId = new URLSearchParams(location.search).get('id') || ''

    useEffect(() => {
        if (isLoading === false) {
            let foundDoc = getDoc(hashId);
            setDoc(foundDoc)
            setPdfLoading(true)
            setPdfError(false)
        }
    }, [isLoading, hashId, getDoc])

    if (isLoading || doc == null) {
        return <div className="portal"><div className="loading">Loading document…</div></div>
    }

    // build CDN PDF link
    let pdfLink = "https://cdn.toxicdocs.org/"
    pdfLink += doc.hash_id.slice(0, 2)
    pdfLink += "/"
    pdfLink += doc.hash_id
    pdfLink += "/"
    pdfLink += doc.hash_id
    pdfLink += ".pdf"

    const getFileName = (filename) => (filename || '').split('/').slice(-1)[0]

    return (
        <div className="doc-page">
            <div className="breadcrumb">
                <a href="/">Home</a>
                {' '} / {' '}
                <a href={`/portal?epaRegion=${encodeURIComponent(doc.region)}`}>Region {doc.region}</a>
                {' '} / {' '}
                <a href={`/portal?statute=${encodeURIComponent(doc.statute)}`}>{doc.statute || 'UNKNOWN'}</a>
                {' '} / {" "}
                {getFileName(doc.original_filename)}
            </div>
            <div className="doc-title-block">
                <div>
                    <h2>{doc.epa_activity_type || 'Document'}</h2>
                    <p className="mono">{getFileName(doc.original_filename)}</p>
                </div>
                <Button href={pdfLink} rel="noreferrer" target="_blank">Download PDF</Button>
            </div>

            <div className="doc-detail">
                <div className="doc-meta">
                    <dl>
                        <dt>Region</dt><dd><span className="tag region">Region {doc.region}</span></dd>
                        <dt>Statute</dt><dd><span className="tag statute">{doc.statute}</span> </dd>
                        <dt>Document Type</dt><dd><span className="tag doctype">{doc.epa_activity_type}</span>{' '}{/* description */}
                            {doc.epa_activity_type === 'INFOREQ' ? ' — Information Request (Section 114 / 308)' : doc.epa_activity_type === 'ENF' ? ' — Enforcement Action' : ''}
                        </dd>
                        <dt>Company / Entity</dt><dd>{doc.peer_corp_name || doc.company || 'FOIA'}</dd>
                        <dt>Year</dt>
                        <dd>
                            <span className="tag year">{doc.year || 'N/A'}</span>
                            &nbsp;
                            <span className="mono">(
                                {doc.created_at && doc.created_at['$date'] ? new Date(doc.created_at['$date']).toISOString().slice(0,10).replace(/-/g,'') : ''}
                            )</span>
                        </dd>
                        <dt>Pages</dt><dd>{doc.num_pages || 'N/A'}</dd>
                        <dt>File Size</dt><dd>{doc.size || doc.file_size}</dd>
                        <dt>Path</dt><dd className="mono" style={{fontSize: '11.5px', wordBreak: 'break-all'}}>{doc.original_filename}</dd>
                    </dl>
                </div>

                <div className="doc-text">
                    <pre>{doc.doc_text || doc.doc_summary || ''}</pre>
                </div>
            </div>
        </div>
    )
}

export default Document;