import { useDocs } from 'data/data'

import Button from 'features/portal/Button'

function Header() {
    const { docs, isLoading, stats } = useDocs()

    const getFileName = (filename) => (filename || '').split('/').slice(-1)[0]

    const formatCsvValue = (value) => {
        const stringValue = value == null ? '' : String(value)
        return '"' + stringValue.replace(/"/g, '""') + '"'
    }

    const downloadCsv = () => {
        if (isLoading || docs == null || docs.length === 0) {
            return
        }

        const headers = ['Facility', 'Summary', 'Region', 'Statute', 'Document', 'Year', 'Pages', 'File Size', 'Added', 'Link', 'Filename', 'Audit Notes', 'Associated Files']

        const rows = docs.map((doc) => {
            let pdfLink = 'https://cdn.toxicdocs.org/'
            pdfLink += doc.hash_id.slice(0, 2)
            pdfLink += '/'
            pdfLink += doc.hash_id
            pdfLink += '/'
            pdfLink += doc.hash_id
            pdfLink += '.pdf'

            const updatedAt = new Date(doc.updated_at['$date'])

            return [
                doc.peer_corp_name,
                doc.doc_summary,
                doc.region,
                doc.statute,
                doc.epa_activity_type,
                doc.year,
                doc.num_pages || doc.pages || '',
                doc.size || '',
                updatedAt.toLocaleDateString(),
                pdfLink,
                getFileName(doc.original_filename),
                doc.audit_notes,
                doc.associted_file,
            ].map(formatCsvValue).join(',')
        })

        const csv = '\ufeff' + [headers.map(formatCsvValue).join(','), ...rows].join('\n')
        const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' })
        const url = window.URL.createObjectURL(blob)
        const link = document.createElement('a')

        link.href = url
        link.download = 'document-results.csv'
        document.body.appendChild(link)
        link.click()
        link.remove()

        window.setTimeout(() => window.URL.revokeObjectURL(url), 0)
    }

    let documentCountBadge = null
    let statuteCountBadges = null

    if (isLoading === false) {
        documentCountBadge = <span className="results-count-badge">{docs.length.toLocaleString()} documents</span>

        let statutes = []
        for (let i = 0; i < stats.statutes.length; i++) {
            let statute = {}
            statute.name = stats.statutes[i]

            statute.count = docs.reduce((arr, cur) => {
                if (cur.statute === statute.name) {
                    return arr+1
                }
                return arr
            }, 0)

            if (statute.count > 0)
                statutes.push(statute)
        }

        statuteCountBadges = statutes.map((a) => {
            if (a.count === 0)
                return null
            return <span className={"badge " + a.name.toLowerCase()} key={a.name}>{a.count.toLocaleString()} {a.name}</span>
        })

    }

    return (
        <>
            <div>
                <div className="dashboard-kicker">
                    Eyes on Environmental Enforcement Records
                </div>

                <div className="results-title">
                    <i className="ti ti-files"></i>
                    <span>Document Results</span>
                    { documentCountBadge }
                    { statuteCountBadges }
                </div>
            </div>

            <div className="results-tools">
                <Button isPrimary={true} onClick={downloadCsv} disabled={isLoading || docs == null || docs.length === 0}>Export CSV</Button>
            </div>
        </>
    )
}

export default Header;