import HeroBasic from '../components/HeroBasic'
import Card from '../components/Card'

function ProjectBackground() {
    var heroTitle = "Project Background"
    var heroSubtitle = "History and development of the Eyes on Environmental Enforcement Project."

    var cardHeader = "Background"
    return (
        <div>
            <HeroBasic title={heroTitle} subtitle={heroSubtitle} />
            <Card header={cardHeader} >
                <p>
                    PEER submitted a FOIA request to EPA to receive enforcement documents that identify potential or actual violations in early 2025. The FOIA was submitted because PEER had concerns that compliance issues identified via inspections would not receive enforcement follow-up. For example, an inspection conducted during the Biden Administration that resulted in a Notice of Violation (pre-cursor to formal enforcement) may not have been acted on after the change in administration. In early 2026, PEER brought two national experts on EPA enforcement and compliance data into the project to organize the data and website. Eric Schaeffer, Former Director of EPA’s Office of Regulatory Enforcement, has been instrumental in curating the files. Mike Barrette, founder and manager of EPA’s Enforcement and Compliance History Online (ECHO) and EPA’s National Targeting Center is taking a lead role in pulling together the technical staff to make this initiative happen. Mike and Eric have worked with PEER staff and contractors including Colleen Zimmerman, Kaylee Rodriguez and Ngan Nguyen. The Environmental Data and Governance Initiative (EDGI) provided PEER with strategic advice and consultation on building out the database. PEER also received significant technical contributions in building out the system from Merlin Chowkwanyun, Associate Professor at Columbia University. The Eyes on Environmental Enforcement Project team is working on exciting future additions to this site. 
                </p>
            </Card>
        </div>
    )
}

export default ProjectBackground