import { createContext, useContext, useState, useEffect, useCallback } from 'react';
import data from './peer-data.js'
import originalFilter from './originalFilter.js';

const DataContext = createContext(null);

const today =  new Date()

function calculateStats(docs) {
    let stats = {}

    stats.size = docs.length.toLocaleString();
    stats.statutes = []

    let epaRegionCount = 0;
    let minYear = 9999;
    let maxYear = 0;
    for (let i = 0; i < docs.length; i++) {
        if (docs[i].year < minYear && docs[i].year != null)
            minYear = docs[i].year
        if (docs[i].year > maxYear && docs[i].year <= today.getFullYear())
            maxYear = docs[i].year
        if (Number(docs[i].region) > epaRegionCount)
            epaRegionCount = Number(docs[i].region)
        if (!stats.statutes.includes(docs[i].statute))
            stats.statutes.push(docs[i].statute)
    }

    stats.statutes.sort((a, b) => a.localeCompare(b))

    stats.epaRegions = epaRegionCount
    stats.minYear = minYear
    stats.maxYear = maxYear

    return stats
}

export function DataProvider({ children }) {
    const [allDocs, setAllDocs] = useState(null);
    const [docs, setDocs] = useState(null);
    const [filter, setFilter] = useState(originalFilter);
    const [isLoading, setLoading] = useState(true);
    const [stats, setStats] = useState({ size: null, epaRegions: null, minYear: "", maxYear: "", statutes: [] });

    useEffect(() => {
        setAllDocs(data);
        setDocs(data);
        setLoading(false);
        setStats(calculateStats(data));
    }, []);

    const applyFilter = useCallback((filterFn, filter) => {
        setDocs(filterFn ? allDocs.filter(filterFn) : allDocs);
        setFilter(filter);
    }, [allDocs]);

    const resetFilter = useCallback(() => {
        setDocs(allDocs);
        setFilter(originalFilter);
    }, [allDocs]);

    const getDoc = useCallback((hashId) => {
        return allDocs.find((a) => a.hash_id === hashId)
    }, [allDocs])

    return (
        <DataContext.Provider value={{ docs, allDocs, isLoading, stats, filter, getDoc, applyFilter, resetFilter }}>
            {children}
        </DataContext.Provider>
    );
}

export function useDocs() {
    return useContext(DataContext);
}