import { useDocs } from 'data/data'
import { Link } from 'react-router'

function Table() {

    let headers = [
        { id: "company", label: "Facility" },
        { id: "summary", label: "Summary" },
        { id: "region", label: "Region" },
        { id: "statute", label: "Statute" },
        { id: "type", label: "Document" },
        { id: "year", label: "Year" },
        { id: "pages", label: "Pages" },
        { id: "size", label: "File Size" },
        { id: "added", label: "Added" },
        { id: "link", label: "Link", isHidden: true },
        { id: "audit_notes", label: "Audit Notes", isHidden: true },
        { id: "associted_files", label: "Associated Files", isHidden: true },
        { id: "filename", label: "Filename" },
    ]

    let headersJsx = headers.map((a, index) => {
        if (a.isHidden)
            return false;
        return (
            <th key={index}>{a.label}</th>
        )
    })


    const { docs, isLoading } = useDocs();

    const getFileName = (filename) => (filename || '').split('/').slice(-1)[0]

    if (isLoading === true) {
        return <div></div>
    }

    let resultsJsx = docs.map((a) => {
        let statuteClass = ""
        let typeClass = ""
        let companyName = a.peer_corp_name || a.company || ""
        let docSummary = a.doc_summary || a.summary || ""
        let associatedFile = a.associated_file || ""
        let auditNotes = a.audit_notes || ""

        if (a.statute)
            statuteClass = "badge " + a.statute.toLocaleLowerCase();

        if (a.epa_activity_type)
            typeClass = "badge " + a.epa_activity_type.toLocaleLowerCase();

        let pdfLink = "https://cdn.toxicdocs.org/"
        pdfLink += a.hash_id.slice(0, 2)
        pdfLink += "/"
        pdfLink += a.hash_id
        pdfLink += "/"
        pdfLink += a.hash_id
        pdfLink += ".pdf"

        let updatedAt = new Date(a.updated_at["$date"])

            return (
            <tr key={a.hash_id}>
                <td>{companyName}</td>
                <td>
                    <div className="file-name-cell">
                        <div className="file-name-summary">{docSummary}</div>
                    </div>
                </td>
                <td>{a.region}</td>
                <td><span className={statuteClass}>{a.statute}</span></td>
                <td><span className={typeClass}>{a.epa_activity_type}</span></td>
                <td>{a.year}</td>
                <td>{a.num_pages || a.pages || 'N/A'}</td>
                <td>{a.size}</td>
                <td>{updatedAt.toLocaleDateString()}</td>
                <td>
                    <Link to={`/document?id=${a.hash_id}`} className="file-name-main-link">
                        <div className="file-name-main">{getFileName(a.original_filename)}</div>
                    </Link>
                </td>
                <td>{a.associted_file}</td>
                <td>{a.audit_notes}</td>
            </tr>
        )
    })

    return (
        <div className="tbl-wrap" >
            <table>
                <thead>
                    <tr>
                        {headersJsx}
                    </tr>
                </thead>
                <tbody>
                    {resultsJsx}
                </tbody>
            </table>
        </div >
    )
}

export default Table;