import { useDocs } from 'data/data'

function RadioButton({ filterValues, onChange }) {
    const { stats } = useDocs()

    let options = []

    for (let i = 0; i < stats.statutes.length; i++) {
        let statute = {}
        statute.label = stats.statutes[i]
        statute.isToggled = filterValues.statute.includes(statute.label)
        options.push(statute)
    }

    let handleChange = (label) => {
        let prev = filterValues.statute
        let next = prev.includes(label)
            ? prev.filter(a => a !== label)
            : [...prev, label]
        
        onChange({ ...filterValues, statute: next })
    }

    let optionRender = options.map((a) => {
        let classList = "tog"
        if (a.isToggled)
            classList += " on"
        return <span onClick={() => handleChange(a.label)} key={a.label} className={classList}>{a.label}</span>
    })

    return (
                <div className="tog-wrap">
                    {optionRender}
                </div>
    )
}

export default RadioButton;