import { useDocs } from "data/data";
import RadioButton from "./RadioButton";
import YearSelection from "components/YearSelection";


function Filter({ values, onChange }) {
    let today = new Date()

    const { stats } = useDocs();

    let epaRegionNumbers = ["HQ"]
    for (let i = 0; i < stats.epaRegions; i++) {
        epaRegionNumbers.push(i+1)
    }

    let epaOptions = epaRegionNumbers.map((a) => {
        return <option key={a} value={a.toString()}>Region {a}</option>
    })

    return (
        <div className="filter-grid">

            <div style={{gridColumn: "span 2"}}>
                <label className="field-label">Keyword Search</label>

                <input 
                    type="text" 
                    placeholder="Facility, keyword…" 
                    value={values.keyword}
                    onChange={e => onChange({ ...values, keyword: e.target.value })}
                />
            </div>

            <div>
                <YearSelection 
                    minValue={2021} 
                    maxValue={today.getFullYear()} 
                    filter={values}
                    onChange={e => onChange({...values, startYear: e.lowRange, endYear: e.highRange })}
                    />
            </div>

            <div>
                <label className="field-label">EPA Region</label>

                <select
                    value={values.epaRegion}
                    onChange={e => onChange({ ...values, epaRegion: e.target.value })}
                >
                    <option value="">All regions</option>
                    {epaOptions}
                </select>
            </div>

            <div>
                <label className="field-label">Enforcement Document</label>

                <select
                    value={values.epaType}
                    onChange={e => onChange({ ...values, epaType: e.target.value })}
                >
                    <option value="">All</option>
                    <option value="INSP">INSP</option>
                    <option value="INFOREQ">INFOREQ</option>
                    <option value="NOV">NOV</option>
                    <option value="ENF">ENF</option>
                    <option value="OTHER">Other</option>
                </select>
            </div>

{/*
            <div>
                <label className="field-label">FOIA Source</label>

                <select
                    value={values.foiaSource}
                    onChange={e => onChange({ ...values, foiaSource: e.target.value })}
                >
                    <option value="">All sources</option>
                    <option value="echo">ECHO</option>
                    <option value="cedri">CEDRI</option>
                    <option value="peerpayload">PEER</option>
                </select>
            </div>
*/}


            <div style={{gridColumn: "span 2"}}>
                <label className="field-label">Environmental Statute</label>
                <RadioButton filterValues={values} onChange={onChange} />
            </div>

        </div>
    )
}

export default Filter;